    (1500104, ''D2615000104'', ''W'', ''IPE_TRIDIG'', 0, 1500204, ''20260305''),
    (1500105, ''D2615000105'', ''I'', ''IPE'', 0, 1500205, ''20260306''),
    (1500106, ''D2615000106'', ''X'', ''IPE'', 0, 1500206, ''20260307''),
    (1500107, ''D2615000107'', ''Q'', ''IPE'', 1, 1500207, ''20260308''),
    (1500108, ''D2615000108'', ''V'', ''MJUD'', 0, 1500208, ''20260309'');
INSERT INTO v2.INSTANCE (INSTN_ID_INSTN, INSTN_NUM_ROLE, INSTN_NOM_COURANT, INSTN_CODE_AFFAIRE, INSTN_DATE_SAISINE_GREFFE, INSTN_ID_AFFRE, INSTN_TYPE_INSTANCE) VALUES
